USE AeroLogix;
GO
-- One row per validation rule. This report intentionally returns failures instead
-- of silently filtering bad data; run after ingestion and warehouse loads.
DECLARE @executedAt datetime2(0)=SYSUTCDATETIME();
DECLARE @report TABLE(TestName varchar(80),Description nvarchar(250),RecordsChecked bigint,FailedRecords bigint);
INSERT @report VALUES
('oltp_duplicate_flight_id','Flight source primary key is unique',(SELECT COUNT_BIG(*) FROM ops.Flight),(SELECT COUNT_BIG(*) FROM (SELECT FlightId FROM ops.Flight GROUP BY FlightId HAVING COUNT(*)>1) q)),
('oltp_duplicate_booking_id','Booking source primary key is unique',(SELECT COUNT_BIG(*) FROM ops.Booking),(SELECT COUNT_BIG(*) FROM (SELECT BookingId FROM ops.Booking GROUP BY BookingId HAVING COUNT(*)>1) q)),
('oltp_duplicate_airport_code','Airport natural key is unique',(SELECT COUNT_BIG(*) FROM ref.Airport),(SELECT COUNT_BIG(*)-COUNT(DISTINCT AirportCode) FROM ref.Airport)),
('oltp_duplicate_flight_business_key','Flight number/date pair is unique',(SELECT COUNT_BIG(*) FROM ops.Flight),(SELECT COUNT_BIG(*) FROM (SELECT FlightNumber,FlightDate FROM ops.Flight GROUP BY FlightNumber,FlightDate HAVING COUNT(*)>1) q)),
('oltp_duplicate_booking_reference','Booking reference is unique',(SELECT COUNT_BIG(*) FROM ops.Booking),(SELECT COUNT_BIG(*)-COUNT(DISTINCT BookingReference) FROM ops.Booking)),
('oltp_orphan_flight_route_aircraft','Flights resolve to a route and aircraft',(SELECT COUNT_BIG(*) FROM ops.Flight),(SELECT COUNT_BIG(*) FROM ops.Flight f LEFT JOIN ref.Route r ON r.RouteId=f.RouteId LEFT JOIN ref.Aircraft a ON a.AircraftId=f.AircraftId WHERE r.RouteId IS NULL OR a.AircraftId IS NULL)),
('oltp_orphan_booking','Bookings resolve to a flight and passenger',(SELECT COUNT_BIG(*) FROM ops.Booking),(SELECT COUNT_BIG(*) FROM ops.Booking b LEFT JOIN ops.Flight f ON f.FlightId=b.FlightId LEFT JOIN ops.Passenger p ON p.PassengerId=b.PassengerId WHERE f.FlightId IS NULL OR p.PassengerId IS NULL)),
('oltp_invalid_airport_code','Airport codes contain exactly three characters',(SELECT COUNT_BIG(*) FROM ref.Airport),(SELECT COUNT_BIG(*) FROM ref.Airport WHERE AirportCode LIKE '%[^A-Z]%' OR LEN(AirportCode)<>3)),
('oltp_invalid_flight_date','Flight date matches scheduled departure date',(SELECT COUNT_BIG(*) FROM ops.Flight),(SELECT COUNT_BIG(*) FROM ops.Flight WHERE FlightDate<>CONVERT(date,ScheduledDeparture))),
('oltp_invalid_fare','Base fare is nonnegative',(SELECT COUNT_BIG(*) FROM ops.Booking),(SELECT COUNT_BIG(*) FROM ops.Booking WHERE BaseFare<0)),
('oltp_invalid_booking_date','Booking timestamp is not in the future',(SELECT COUNT_BIG(*) FROM ops.Booking),(SELECT COUNT_BIG(*) FROM ops.Booking WHERE BookedAt>SYSUTCDATETIME())),
('oltp_invalid_flight_status','Flight status is in the business domain',(SELECT COUNT_BIG(*) FROM ops.Flight),(SELECT COUNT_BIG(*) FROM ops.Flight WHERE FlightStatus NOT IN('SCHEDULED','COMPLETED','CANCELLED','DIVERTED'))),
('oltp_invalid_booking_status','Booking status is in the business domain',(SELECT COUNT_BIG(*) FROM ops.Booking),(SELECT COUNT_BIG(*) FROM ops.Booking WHERE BookingStatus NOT IN('BOOKED','TICKETED','FLOWN','CANCELLED'))),
('oltp_invalid_aircraft_capacity','Aircraft capacity is between 1 and 600',(SELECT COUNT_BIG(*) FROM ref.Aircraft),(SELECT COUNT_BIG(*) FROM ref.Aircraft WHERE SeatCapacity NOT BETWEEN 1 AND 600)),
('oltp_missing_required_values','Required operational columns are populated',(SELECT COUNT_BIG(*) FROM ops.Flight)+(SELECT COUNT_BIG(*) FROM ops.Booking),(SELECT COUNT_BIG(*) FROM ops.Flight WHERE FlightId IS NULL OR FlightDate IS NULL OR RouteId IS NULL OR AircraftId IS NULL)+(SELECT COUNT_BIG(*) FROM ops.Booking WHERE BookingId IS NULL OR FlightId IS NULL OR PassengerId IS NULL OR BookedAt IS NULL)),
('oltp_invalid_passenger_capacity','Non-cancelled booking count does not exceed aircraft capacity',(SELECT COUNT_BIG(*) FROM ops.Flight),(SELECT COUNT_BIG(*) FROM ops.Flight f JOIN ops.Booking b ON b.FlightId=f.FlightId AND b.BookingStatus<>'CANCELLED' JOIN ref.Aircraft a ON a.AircraftId=f.AircraftId GROUP BY f.FlightId,a.SeatCapacity HAVING COUNT(*)>a.SeatCapacity)),
('oltp_invalid_route','Routes have different known endpoints and positive distance',(SELECT COUNT_BIG(*) FROM ref.Route),(SELECT COUNT_BIG(*) FROM ref.Route r LEFT JOIN ref.Airport o ON o.AirportCode=r.OriginAirportCode LEFT JOIN ref.Airport d ON d.AirportCode=r.DestinationAirportCode WHERE r.OriginAirportCode=r.DestinationAirportCode OR r.DistanceMiles<=0 OR o.AirportCode IS NULL OR d.AirportCode IS NULL)),
('warehouse_missing_flight_dimensions','Flight facts resolve to required dimensions',(SELECT COUNT_BIG(*) FROM dw.FactFlight),(SELECT COUNT_BIG(*) FROM dw.FactFlight f LEFT JOIN dw.DimDate d ON d.DateKey=f.FlightDateKey LEFT JOIN dw.DimAirport o ON o.AirportKey=f.OriginAirportKey LEFT JOIN dw.DimAirport x ON x.AirportKey=f.DestinationAirportKey LEFT JOIN dw.DimAircraft a ON a.AircraftKey=f.AircraftKey WHERE d.DateKey IS NULL OR o.AirportKey IS NULL OR x.AirportKey IS NULL OR a.AircraftKey IS NULL)),
('warehouse_missing_booking_dimensions','Booking facts resolve to required dimensions',(SELECT COUNT_BIG(*) FROM dw.FactBooking),(SELECT COUNT_BIG(*) FROM dw.FactBooking b LEFT JOIN dw.DimDate d ON d.DateKey=b.FlightDateKey LEFT JOIN dw.DimPassenger p ON p.PassengerKey=b.PassengerKey LEFT JOIN dw.DimAirport o ON o.AirportKey=b.OriginAirportKey LEFT JOIN dw.DimAirport x ON x.AirportKey=b.DestinationAirportKey WHERE d.DateKey IS NULL OR p.PassengerKey IS NULL OR o.AirportKey IS NULL OR x.AirportKey IS NULL)),
('warehouse_duplicate_flight_fact','There is one fact per flight',(SELECT COUNT_BIG(*) FROM dw.FactFlight),(SELECT COUNT_BIG(*) FROM (SELECT FlightId FROM dw.FactFlight GROUP BY FlightId HAVING COUNT(*)>1) q)),
('warehouse_duplicate_booking_fact','There is one fact per booking',(SELECT COUNT_BIG(*) FROM dw.FactBooking),(SELECT COUNT_BIG(*) FROM (SELECT BookingId FROM dw.FactBooking GROUP BY BookingId HAVING COUNT(*)>1) q)),
('scd2_multiple_current_airport','At most one current version exists per airport',(SELECT COUNT_BIG(*) FROM dw.DimAirport),(SELECT COUNT_BIG(*) FROM (SELECT AirportCode FROM dw.DimAirport WHERE IsCurrent=1 GROUP BY AirportCode HAVING COUNT(*)>1) q)),
('scd2_overlapping_airport_versions','Airport effective intervals do not overlap',(SELECT COUNT_BIG(*) FROM dw.DimAirport a),(SELECT COUNT_BIG(*) FROM dw.DimAirport a JOIN dw.DimAirport b ON b.AirportCode=a.AirportCode AND b.AirportKey>a.AirportKey AND a.ValidFrom<COALESCE(b.ValidTo,CONVERT(datetime2,'9999-12-31')) AND b.ValidFrom<COALESCE(a.ValidTo,CONVERT(datetime2,'9999-12-31')))),
('snapshot_matches_service_facts','Service-date snapshots equal latest flight and booking aggregates',(SELECT COUNT_BIG(*) FROM dw.FactDailyFlightSnapshot),(SELECT COUNT_BIG(*) FROM dw.FactDailyFlightSnapshot s JOIN ops.Flight f ON f.FlightId=s.FlightId OUTER APPLY(SELECT COUNT_BIG(*) BookingCount,COALESCE(SUM(CASE WHEN BookingStatus<>'CANCELLED' THEN BaseFare ELSE 0 END),0) Revenue FROM ops.Booking WHERE FlightId=f.FlightId) b WHERE s.SnapshotDateKey<>CONVERT(int,CONVERT(char(8),f.FlightDate,112)) OR s.FlightStatus<>f.FlightStatus OR s.BookingCount<>b.BookingCount OR s.Revenue<>b.Revenue));
SELECT TestName,Description,RecordsChecked,FailedRecords,IIF(FailedRecords=0,'PASS','FAIL') Status,@executedAt ExecutionTimestamp
FROM @report ORDER BY CASE WHEN FailedRecords=0 THEN 1 ELSE 0 END,TestName;
GO
